import sys
from collections import deque


def solve() -> None:
    """统计每个 '#' 区域是否每个格子都临水，输出完全淹没的区域数"""
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    grid = data[1:1 + n]

    seen = [[False] * n for _ in range(n)]
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    fully_submerged = 0

    for i in range(n):
        for j in range(n):
            if grid[i][j] != '#' or seen[i][j]:
                continue
            # 找到一个新区域，BFS 收集它所有格子
            seen[i][j] = True
            queue = deque([(i, j)])
            every_cell_touches_water = True
            while queue:
                x, y = queue.popleft()
                touches_water = False
                for dx, dy in dirs:
                    nx, ny = x + dx, y + dy
                    if not (0 <= nx < n and 0 <= ny < n):
                        touches_water = True          # 出界也算临水
                    elif grid[nx][ny] == '.':
                        touches_water = True
                    elif not seen[nx][ny]:
                        seen[nx][ny] = True
                        queue.append((nx, ny))
                if not touches_water:
                    every_cell_touches_water = False
            if every_cell_touches_water:
                fully_submerged += 1

    sys.stdout.write(str(fully_submerged) + "\n")


if __name__ == "__main__":
    solve()
